/**
 * n8n – Code node
 * Mode : Run Once for All Items
 * Objectif :
 *   1. Repère **gras** ou *gras*
 *   2. Convertit le contenu en lettres "Unicode Bold"
 *   3. Supprime tous les astérisques
 */

const FIELD = 'output'; // ← mets ici le nom exact du champ texte

// --- petite fonction de conversion ASCII → Unicode gras
function toUnicodeBold(str) {
  const upperOffset = 0x1D400 - 0x41;      // A → 𝐀
  const lowerOffset = 0x1D41A - 0x61;      // a → 𝐚
  const digitOffset = 0x1D7CE - 0x30;      // 0 → 𝟎

  return str.split('').map(ch => {
    const code = ch.charCodeAt(0);
    if (code >= 0x41 && code <= 0x5A) return String.fromCodePoint(code + upperOffset); // A-Z
    if (code >= 0x61 && code <= 0x7A) return String.fromCodePoint(code + lowerOffset); // a-z
    if (code >= 0x30 && code <= 0x39) return String.fromCodePoint(code + digitOffset); // 0-9
    return ch; // ponctuation, espaces…
  }).join('');
}

for (const item of $input.all()) {
  if (item.json[FIELD]) {
    item.json[FIELD] = item.json[FIELD]
      // ► 1. **…**  ou *…*  → conversion + suppression d’astérisques
      .replace(/\*{1,2}([^*]+?)\*{1,2}/gs, (_, txt) => toUnicodeBold(txt))

      // ► 2. S’il reste des astérisques isolés → on les retire
      .replace(/\*/g, '');
  }
}

return $input.all();

