const store = $getWorkflowStaticData('global');
const VERSION = 'mediassist-v4-deterministic-appointment';
if (store.__version !== VERSION) {
  for (const key of Object.keys(store)) delete store[key];
  store.__version = VERSION;
}

const EVENT_TYPE_ID = 7143715;
const DEPARTMENTS = ['General Physician', 'Dentist', 'Cardiology', 'Orthopedics', 'Dermatology'];
const DOCTORS = {
