    { id: 'DR008', name: 'Dr. Kabir Menon', exp: 14, slots: ['Monday 09:00-12:00','Tuesday 09:00-12:00','Tuesday 17:00-20:00','Wednesday 09:00-12:00','Thursday 09:00-12:00','Thursday 17:00-20:00','Friday 09:00-12:00','Saturday 09:00-13:00'] },
  ],
