    { id: 'DR009', name: 'Dr. Anita Rao', exp: 7, slots: ['Monday 10:00-13:00','Monday 15:00-18:00','Tuesday 10:00-13:00','Wednesday 10:00-13:00','Wednesday 15:00-18:00','Thursday 10:00-13:00','Friday 10:00-13:00'] },
    { id: 'DR010', name: 'Dr. Rohan Malhotra', exp: 11, slots: ['Monday 16:00-20:00','Tuesday 16:00-20:00','Thursday 16:00-20:00','Friday 16:00-20:00','Saturday 11:00-15:00'] },
  ],
};
const DAY_INDEX = { Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5, Saturday: 6 };

function greeting() {
  return 'Hello, welcome to City Clinic, Kota!\n\nHow may I help you?\n\nPlease select your preferred language.\nकृपया अपनी पसंदीदा भाषा चुनें।\n\n1. English\n2. Hindi';
}
function mainMenu(lang) {
  if (lang === 'hi') return 'मुख्य मेनू\n\n1. अपॉइंटमेंट बुक करें\n2. समस्या उठाएँ\n3. शिकायत उठाएँ\n4. बुकिंग खोजें\n5. बुकिंग रद्द करें\n6. बुकिंग पुनर्निर्धारित करें\n7. मुख्य मेनू पर वापस जाएँ\n\nकृपया अपना विकल्प 1-7 लिखें।';
  return 'Main Menu\n\n1. Book an Appointment\n2. Raise an Issue\n3. Raise a Complaint\n4. Find Booking\n5. Cancel Booking\n6. Reschedule Booking\n7. Back to Main Menu\n\nPlease reply with the number of your choice (1-7).';
}
function bookStart() {
  return 'Do you already know the department or doctor you want to visit?\n\n1. Yes, I know the department or doctor\n2. No, help me choose\n3. Go Back\n4. Main Menu\n\nPlease reply with 1, 2, 3, or 4.';
}
function deptMenu() {
  return 'Please select a department:\n\n1. General Physician\n2. Dentist\n3. Cardiology\n4. Orthopedics\n5. Dermatology\n6. Go Back\n7. Main Menu\n\nPlease reply with 1, 2, 3, 4, 5, 6, or 7.';
}
function doctorMenu(dept) {
  const docs = DOCTORS[dept];
  return `${dept} - Choose a doctor:\n\n1. ${docs[0].name} (${docs[0].exp} years experience)\n2. ${docs[1].name} (${docs[1].exp} years experience)\n3. Go Back\n4. Main Menu\n\nPlease reply with 1, 2, 3, or 4.`;
}
function slotMenu(doc) {
  const lines = doc.slots.map((slot, i) => `${i + 1}. ${slot}`);
  lines.push(`${doc.slots.length + 1}. Go Back`, `${doc.slots.length + 2}. Main Menu`);
  return `${doc.name} - Available slots:\n\n${lines.join('\n')}\n\nPlease reply with the number of your choice.`;
}
function detailsPrompt() {
  return 'To complete the booking, please provide the following details in one message:\n\n1. Full name\n2. Email address\n3. Phone number\n4. Reason for the appointment\n5. Go Back\n6. Main Menu';
}
function askSymptoms() {
  return 'Please describe your symptoms so I can guide you to the right department.\n\n1. Go Back\n2. Main Menu';
}
function recommendDept(text) {
  const low = text.toLowerCase();
  if (/tooth|teeth|gum|cavity|dental|दांत|दाँत/.test(low)) return 'Dentist';
  if (/chest|heart|bp|blood pressure|pulse|cardio|दिल/.test(low)) return 'Cardiology';
  if (/bone|joint|knee|back|fracture|shoulder|orthopedic|हड्डी|घुटना|कमर/.test(low)) return 'Orthopedics';
  if (/skin|rash|acne|itch|allergy|derma|त्वचा|खुजली/.test(low)) return 'Dermatology';
  return 'General Physician';
}
function indiaDateParts() {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
  const v = Object.fromEntries(parts.filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
  return { y: Number(v.year), m: Number(v.month), d: Number(v.day) };
}
function nextDateFor(dayName) {
  const p = indiaDateParts();
  const base = new Date(Date.UTC(p.y, p.m - 1, p.d));
  const today = base.getUTCDay();
  let diff = (DAY_INDEX[dayName] - today + 7) % 7;
  if (diff === 0) diff = 7;
  base.setUTCDate(base.getUTCDate() + diff);
  return base.toISOString().slice(0, 10);
}
function toUtc(date, startTime) {
  return new Date(`${date}T${startTime}:00+05:30`).toISOString();
}
function normalizePhone(raw) {
  const digits = String(raw || '').replace(/\D/g, '');
  if (digits.length === 10) return `+91${digits}`;
  if (digits.length === 12 && digits.startsWith('91')) return `+${digits}`;
  if (digits.length === 13 && digits.startsWith('091')) return `+${digits.slice(1)}`;
  return raw && raw.startsWith('+') ? raw : `+${digits}`;
}
function parseDetails(text) {
  const email = (text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) || [])[0] || '';
  const phoneRaw = (text.match(/(?:\+?91[\s-]?)?[6-9]\d{9}/) || [])[0] || '';
  let cleaned = text.replace(email, '').replace(phoneRaw, '');
  cleaned = cleaned.replace(/name\s*:/ig, '').replace(/email\s*:/ig, '').replace(/phone\s*:/ig, '').replace(/reason\s*:/ig, '');
  const lines = cleaned.split(/\n|,/).map(x => x.trim()).filter(Boolean);
  const name = lines[0] || '';
  const reason = lines.slice(1).join(' ') || '';
  return { name, email, phone: normalizePhone(phoneRaw), reason };
}
function confirmMessage(a) {
  return `Please confirm your appointment details:\n\nDoctor: ${a.doctor}\nDepartment: ${a.department}\nSlot: ${a.slotLabel}\nName: ${a.name}\nEmail: ${a.email}\nPhone: ${a.phone}\nReason: ${a.reason}\n\n1. Confirm Booking\n2. Edit Details\n3. Go Back\n4. Main Menu`;
}
function resetMain(s) {
  s.route = 'menu';
  s.step = 'main';
  s.appt = {};
}
function isGreeting(text) {
  return /^(hi+|hello+|hey+|namaste|नमस्ते|good morning|good evening)$/i.test(text.trim());
}
function wantsMain(text) {
  const low = text.toLowerCase();
  return low === 'main menu' || low === 'menu' || low.includes('मुख्य मेनू');
}

const out = [];
for (const item of $input.all()) {
  const chatId = String(item.json.message?.chat?.id || 'unknown');
  const text = String(item.json.message?.text || '').trim();
  const low = text.toLowerCase();
  let s = store[chatId] || { step: 'idle', lang: 'en', route: 'menu', appt: {} };
  let route = 'reply';
  let output = '';
  let user_prompt = text;

  if (isGreeting(text)) {
    s = { step: 'language', lang: 'en', route: 'menu', appt: {} };
    output = greeting();
  } else if (s.step === 'language') {
    if (text === '1' || low.includes('english')) {
      s = { step: 'main', lang: 'en', route: 'menu', appt: {} };
      output = mainMenu('en');
    } else if (text === '2' || low.includes('hindi') || low.includes('हिंदी')) {
      s = { step: 'main', lang: 'hi', route: 'menu', appt: {} };
      output = mainMenu('hi');
    } else {
      output = greeting();
    }
  } else if (wantsMain(text)) {
    resetMain(s);
    output = mainMenu(s.lang || 'en');
  } else if (s.step === 'main' || s.route === 'menu') {
    if (text === '1') {
      s.route = 'appointment'; s.step = 'book_start'; s.appt = {};
      output = bookStart();
    } else if (text === '2' || text === '3') {
      s.route = 'ticket'; s.step = 'in_ticket';
      route = 'ticket'; user_prompt = text === '2' ? 'START_ISSUE' : 'START_COMPLAINT';
    } else if (text === '4') {
      s.route = 'appointment'; s.step = 'find_email';
      output = 'Please provide the email address used for the booking.\n\n1. Go Back\n2. Main Menu';
    } else if (text === '5') {
      s.route = 'appointment'; s.step = 'cancel_email';
      output = 'Please provide the email address used for the booking you want to cancel.\n\n1. Go Back\n2. Main Menu';
    } else if (text === '6') {
      s.route = 'appointment'; s.step = 'reschedule_email';
      output = 'Please provide the email address used for the booking you want to reschedule.\n\n1. Go Back\n2. Main Menu';
    } else {
      output = mainMenu(s.lang || 'en');
    }
  } else if (s.route === 'ticket') {
    route = 'ticket';
    user_prompt = text;
  } else if (s.route === 'appointment') {
    const a = s.appt || {};
    if (s.step === 'book_start') {
      if (text === '1') { s.step = 'dept_select'; output = deptMenu(); }
      else if (text === '2') { s.step = 'symptoms'; output = askSymptoms(); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'dept_select') {
      const idx = Number(text);
      if (idx >= 1 && idx <= 5) { a.department = DEPARTMENTS[idx - 1]; s.appt = a; s.step = 'doctor_select'; output = doctorMenu(a.department); }
      else if (text === '6') { s.step = 'book_start'; output = bookStart(); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'symptoms') {
      if (text === '1') { s.step = 'book_start'; output = bookStart(); }
      else if (text === '2') { resetMain(s); output = mainMenu(s.lang || 'en'); }
      else { a.department = recommendDept(text); s.appt = a; s.step = 'recommend_confirm'; output = `Based on your symptoms, I recommend ${a.department}.\n\nDo you want to proceed with this department?\n\n1. Yes\n2. No\n3. Go Back\n4. Main Menu`; }
    } else if (s.step === 'recommend_confirm') {
      if (text === '1') { s.step = 'doctor_select'; output = doctorMenu(a.department); }
      else if (text === '2') { s.step = 'dept_select'; output = deptMenu(); }
      else if (text === '3') { s.step = 'symptoms'; output = askSymptoms(); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'doctor_select') {
      const docs = DOCTORS[a.department] || [];
      if (text === '1' || text === '2') { const doc = docs[Number(text) - 1]; a.doctor = doc.name; a.doctorId = doc.id; a.doctorIndex = Number(text) - 1; s.appt = a; s.step = 'slot_select'; output = slotMenu(doc); }
      else if (text === '3') { s.step = 'dept_select'; output = deptMenu(); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'slot_select') {
      const doc = (DOCTORS[a.department] || [])[a.doctorIndex];
      const idx = Number(text);
      if (doc && idx >= 1 && idx <= doc.slots.length) {
        const slot = doc.slots[idx - 1];
        const [day, timeRange] = slot.split(' ');
        const startTime = timeRange.split('-')[0];
        const date = nextDateFor(day);
        a.slot = slot; a.slotLabel = `${day} ${date} ${timeRange}`; a.date = date; a.startTime = startTime; a.eventDateTimeUtc = toUtc(date, startTime);
        s.appt = a; s.step = 'details'; output = detailsPrompt();
      } else if (doc && idx === doc.slots.length + 1) { s.step = 'doctor_select'; output = doctorMenu(a.department); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'details') {
      if (text === '5') { s.step = 'slot_select'; const doc = (DOCTORS[a.department] || [])[a.doctorIndex]; output = slotMenu(doc); }
      else if (text === '6') { resetMain(s); output = mainMenu(s.lang || 'en'); }
      else {
        const d = parseDetails(text);
        Object.assign(a, d);
        s.appt = a;
        if (!a.name || !a.email || !a.phone || !a.reason) output = `I could not read all details clearly. Please send full name, email address, phone number, and reason in one message.\n\n5. Go Back\n6. Main Menu`;
        else { s.step = 'confirm_booking'; output = confirmMessage(a); }
      }
    } else if (s.step === 'confirm_booking') {
      if (text === '1') {
        route = 'appointment';
        user_prompt = `BOOK_APPOINTMENT_CONFIRMED\n${JSON.stringify({ eventTypeId: EVENT_TYPE_ID, doctorId: a.doctorId, doctor: a.doctor, department: a.department, slot: a.slotLabel, eventDateTimeUtc: a.eventDateTimeUtc, name: a.name, email: a.email, phoneE164: a.phone, reason: a.reason }, null, 2)}`;
        resetMain(s);
      } else if (text === '2') { s.step = 'details'; output = detailsPrompt(); }
      else if (text === '3') { s.step = 'slot_select'; const doc = (DOCTORS[a.department] || [])[a.doctorIndex]; output = slotMenu(doc); }
      else { resetMain(s); output = mainMenu(s.lang || 'en'); }
    } else if (s.step === 'find_email') {
      if (text === '1' || text === '2') { resetMain(s); output = mainMenu(s.lang || 'en'); }
      else { route = 'appointment'; user_prompt = `FIND_BOOKING\nEmail: ${text}\nEventTypeId: ${EVENT_TYPE_ID}`; resetMain(s); }
    } else if (s.step === 'cancel_email') {
      if (text === '1' || text === '2') { resetMain(s); output = mainMenu(s.lang || 'en'); }
      else { route = 'appointment'; user_prompt = `CANCEL_BOOKING_START\nEmail: ${text}\nEventTypeId: ${EVENT_TYPE_ID}\nFind the booking and ask the user to confirm before cancelling.`; s.step = 'cancel_ai'; }
    } else if (s.step === 'reschedule_email') {
      if (text === '1' || text === '2') { resetMain(s); output = mainMenu(s.lang || 'en'); }
      else { route = 'appointment'; user_prompt = `RESCHEDULE_BOOKING_START\nEmail: ${text}\nEventTypeId: ${EVENT_TYPE_ID}\nFind the booking and ask the user for the new slot before rescheduling.`; s.step = 'reschedule_ai'; }
    } else if (s.step === 'cancel_ai' || s.step === 'reschedule_ai') {
      route = 'appointment'; user_prompt = text;
    } else {
      resetMain(s); output = mainMenu(s.lang || 'en');
    }
  } else {
    resetMain(s);
    output = mainMenu(s.lang || 'en');
  }

  store[chatId] = s;
  out.push({ json: { ...item.json, route, output, user_prompt, selectedLanguage: s.lang || 'en' } });
}
return out;

const greetingPattern = /^(\/start(?:@\w+)?|hi+|hello+|hey+|namaste|नमस्ते|good morning|good evening)[\s.!?]*$/i;

return $input.all().map((item) => {
  const message = item.json.message;
  const text = String(message?.text || '').trim();

  if (message && greetingPattern.test(text)) {
    message.text = 'hi';
    item.json.user_prompt = 'hi';
    item.json.resetGreeting = true;
  }

  return item;
});
